INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2201, 'Exodus 26:36', 'Exodus', 26, 36, '&nbsp;د خېمې د ننوتلو دروازې دپاره د کتان نه يوه پړده جوړه کړه چې د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه تياره شوې وى او چې دا په ګُلکارۍ باندې ښائسته کړے شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2202, 'Exodus 26:37', 'Exodus', 26, 37, '&nbsp;د دې پړدې دپاره د سرو زرو کُنډې جوړې کړه او د کيکر لرګى نه پينځۀ ستنې جوړې کړه چې د سرو زرو پترى ورباندې خېژولے شوى وى، او د دې ستنو دپاره پينځۀ د زېړو پښې جوړې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2203, 'Exodus 27:1', 'Exodus', 27, 1, '&nbsp;د کيکر لرګى نه يوه قربان‌ګاه جوړه کړه. هغه به څلور‌ګوټه وى، چې اووۀ نيم فټه اوږده وى، اووۀ نيم فټه پلنه او څلور نيم فټه لوړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2204, 'Exodus 27:2', 'Exodus', 27, 2, '&nbsp;د دې دپاره د څلورو ګوټونو دپاسه د ښکرو په شان څيزونه جوړ کړه چې د قربان‌ګاه سره يو ځائ شى او په دې هر څۀ باندې به د زېړو پترى وخېژولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2205, 'Exodus 27:3', 'Exodus', 27, 3, '&nbsp;د ايرو د لرې کولو دپاره لوښى، بېلچې، جامونه، درې غاښى او د ګرمې ايرې دپاره لوښى جوړ کړه. دا ټول سامان د زېړو نه جوړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2206, 'Exodus 27:4', 'Exodus', 27, 4, '&nbsp;او تۀ د زېړو يوه جالۍ هم جوړه کړه او د هغې په ګوټونو باندې د وړلو دپاره څلور د زېړو کَړۍ ولګوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2207, 'Exodus 27:5', 'Exodus', 27, 5, '&nbsp;دا جالۍ د قربان‌ګاه د ژۍ لاندې کېږده نو چې د قربان‌ګاه مينځ ته ورسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2208, 'Exodus 27:6', 'Exodus', 27, 6, '&nbsp;د وړلو دپاره د کيکر لرګى نه ورله بازوګان جوړ کړه او د زېړو پترى ورباندې وخېژوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2209, 'Exodus 27:7', 'Exodus', 27, 7, '&nbsp;نو د قربان‌ګاه دواړو طرفونو ته چې کومې کَړۍ دى په هغې کښې بازوګان ولګوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2210, 'Exodus 27:8', 'Exodus', 27, 8, '&nbsp;قربان‌ګاه د تختو نه جوړه کړه او تشه يې پرېږده، هم د هغې نقشې په مطابق چې ما درته په غرۀ باندې ښودلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2211, 'Exodus 27:9', 'Exodus', 27, 9, '&nbsp;د کتان د پړدو نه زما د حضور خېمې دپاره دربار جوړ کړه چې د جنوب طرف يې پنځوس ګزه اوږد وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2212, 'Exodus 27:10', 'Exodus', 27, 10, '&nbsp;دا به د زېړو د شلو ستنو په ذريعه د زېړو په شلو پښو کښې، د سپينو زرو کُنډو او د سپينو زرو سيخونو په مدد سره ټينګولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2213, 'Exodus 27:11', 'Exodus', 27, 11, '&nbsp;د دربار شمال طرف ته دې هم دغه شان وکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2214, 'Exodus 27:12', 'Exodus', 27, 12, '&nbsp;په نمرپرېواتۀ طرف به د لسو ستنو او لسو پښو سره پينځويشت ګزه اوږدې پړدې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2215, 'Exodus 27:13', 'Exodus', 27, 13, '&nbsp;نمرخاتۀ طرف دربار به هم پينځويشت ګزه اوږد وى، چې هلته دروازه هم ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2216, 'Exodus 27:16', 'Exodus', 27, 16, '&nbsp;يواځې دروازې له دې لس ګزه اوږده پړده وى چې د کتان نه جوړه شوې وى چې د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه تياره شوې وى او په ګُلکارۍ باندې ښائسته کړے شوې وى. دا دې د څلورو ستنو او څلورو پښو په ذريعه ټينګه کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2217, 'Exodus 27:17', 'Exodus', 27, 17, '&nbsp;د دربار ګېرچاپېره ټولې ستنې به د سپينو زرو د سيخونو سره انښلولے شى او د هغې کُنډې به د سپينو زرو وى او پښې به يې زېړو نه جوړولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2218, 'Exodus 27:18', 'Exodus', 27, 18, '&nbsp;دا دربار به پنځوس ګزه اوږد وى او پينځويشت ګزه پلن وى او دوه نيم ګزه لوړ وى. د دې پړدې به د کتان نه او پښې به يې د زېړو نه جوړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2219, 'Exodus 27:19', 'Exodus', 27, 19, '&nbsp;په خېمه کښې چې څومره سامان استعماليږى او د خېمې او دربار دپاره ټول موږى به د زېړو نه جوړولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2220, 'Exodus 27:20', 'Exodus', 27, 20, '&nbsp;بنى اِسرائيلو له حُکم ورکړه چې د ډيوې دپاره د زيتُونو سوچه تېل درله راوړى، چې دا هره شپه بله وساتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2221, 'Exodus 27:21', 'Exodus', 27, 21, '&nbsp;هارون او د هغۀ زامن دې هغه ډيوه زما د حضور په خېمه کښې د پړدې نه بهر ولګوى چې د لوظ صندوق ته مخامخ ده. دا به هلته زما په حضور کښې د ماښام نه واخله تر سحره پورې بليږى. بنى اِسرائيل او د هغوئ اولاد به همېشه دپاره دا حُکم منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2222, 'Exodus 28:1', 'Exodus', 28, 1, '&nbsp;خپل ورور هارون او د هغۀ زامن، ندب، ابيهُو، اِلى‌عزر او اِتمر ځان له راوله. هغوئ د بنى اِسرائيلو د مينځ نه رابېل کړه، چې د اِمامانو په توګه زما خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2223, 'Exodus 28:2', 'Exodus', 28, 2, '&nbsp;د خپل ورور هارون دپاره د اِمامانو جامې جوړې کړه، چې هغۀ ته عزت او ښائست مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2224, 'Exodus 28:3', 'Exodus', 28, 3, '&nbsp;ټول ماهِر خلق راوغواړه کومو له چې ما مهارت ورکړے دے او هغوئ ته ووايه چې د هارون جامې جوړې کړى، نو چې هغه د يو اِمام په توګه زما خِدمت ته وقف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2225, 'Exodus 28:4', 'Exodus', 28, 4, '&nbsp;هغوئ ته ووايه چې يو د سينې جېب، يو پېش بند، يوه چُوغه، يو قميص چې ګُلکارى ورباندې شوې وى، يو پټکے او يو کمربند جوړ کړى. هغوئ به د اِمامانو دا جامې ستا ورور هارون او د هغۀ زامنو له جوړوى، چې دوئ د اِمامانو په توګه زما خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2226, 'Exodus 28:5', 'Exodus', 28, 5, '&nbsp;هغه ماهِر خلق به د آسمانى رنګ، کاسنى او سور رنګ وړۍ، د سرو زرو تار او د کتان نه کار اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2227, 'Exodus 28:6', 'Exodus', 28, 6, '&nbsp;هغوئ به پېش بند د آسمانى رنګ، کاسنى او سور رنګ وړۍ، د سرو زرو تار او د کتان نه جوړوى، چې په ګُلکارۍ باندې ښائسته کړے شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2228, 'Exodus 28:7', 'Exodus', 28, 7, '&nbsp;دواړو طرفونو ته دې ورباندې د اوږې پټۍ لګېدلې وى، چې د دې په ذريعه تړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2229, 'Exodus 28:8', 'Exodus', 28, 8, '&nbsp;يو ښۀ ګُلکارى شوے کمربند چې د سرو زرو آسمانى او کاسنى او سور رنګ تارونو نه جوړ وى هغه دې د پېش بند سره ونښلولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2230, 'Exodus 28:9', 'Exodus', 28, 9, '&nbsp;دوه اونيکس کاڼى واخله او په هغې باندې د يعقوب د دولسو زامنو نومونه پاخۀ وليکه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2231, 'Exodus 28:10', 'Exodus', 28, 10, '&nbsp;د هغوئ د پېدايښت په مطابق چې شپږ نومونه په يو کاڼى او شپږ په بل کاڼى باندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2232, 'Exodus 28:11', 'Exodus', 28, 11, '&nbsp;په هغه دوو کاڼو باندې د يعقوب د زامنو نومونه د يو ماهِر زرګر په ذريعه وليکه او دا کاڼى په سرو زرو کښې ګېر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2233, 'Exodus 28:12', 'Exodus', 28, 12, '&nbsp;دا د پېش بند د ولى په پټو باندې ولګوه چې د بنى اِسرائيلو د دولسو قبيلو نمائندګى کوى. نو داسې هارون به د هغوئ نومونه ګرځوى، نو زۀ، مالِک خُدائ به خپل خلق همېشه دپاره ياد ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2234, 'Exodus 28:13', 'Exodus', 28, 13, '&nbsp;د سرو زرو دوه نور څيزونه جوړ کړه چې دا کاڼى په کښې ګېرولے شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2235, 'Exodus 28:14', 'Exodus', 28, 14, '&nbsp;او دوه د سوچه سرو زرو زنځيرونه جوړ کړه چې د تارونو په شان تاو شوى وى او د سرو زرو په دې څيزونو پورې يې ونښلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2236, 'Exodus 28:15', 'Exodus', 28, 15, '&nbsp;د مشر اِمام دپاره يو د سينې جېب جوړ کړه چې د خُدائ پاک رضا معلومولو دپاره يې استعمالوى. دا به هم د هغه کتان نه جوړ وى د کوم نه چې پېش بند جوړ دے او هم هغه شان ګُلکارى به ورباندې شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2237, 'Exodus 28:16', 'Exodus', 28, 16, '&nbsp;دا به څلور‌ګوټه او دوه غبرګه وى، نهۀ اِنچۍ به اوږد او نهۀ اِنچۍ پلن وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2238, 'Exodus 28:17', 'Exodus', 28, 17, '&nbsp;په هغه څلور قطاره قيمتى کاڼى ولګوه، په اول قطار کښې ياقوت، يو طوپاز او يو لعل ولګوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2239, 'Exodus 28:18', 'Exodus', 28, 18, '&nbsp;په دوېم قطار کښې يو زمرد، يو نيلم او يوه هيره ولګوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2240, 'Exodus 28:19', 'Exodus', 28, 19, '&nbsp;په درېم قطار کښې يو کائنائټ، يو عقيق او يو کټېله ولګوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2241, 'Exodus 28:20', 'Exodus', 28, 20, '&nbsp;او په څلورم قطار کښې يو ايکوامرين، يو اونيکس کاڼے او يو جاسپر ولګوه. دا به په سرو زرو کښې ګېر شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2242, 'Exodus 28:21', 'Exodus', 28, 21, '&nbsp;په دې دولسو کاڼو په هر يو کاڼى باندې دې د يعقوب د يو زوئ نوم ليکلے وى، چې د بنى اِسرائيلو د دولسو قبيلو نمائندګى وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2243, 'Exodus 28:22', 'Exodus', 28, 22, '&nbsp;د سينې جېب دپاره د سوچه سرو زرو زنځيرونه جوړ کړه، چې د تارونو په شان تاو شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2244, 'Exodus 28:23', 'Exodus', 28, 23, '&nbsp;د سرو زرو دوه کَړۍ جوړې کړه او د سينې د جېب په برنو ګوټونو پورې يې ونښلوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2245, 'Exodus 28:24', 'Exodus', 28, 24, '&nbsp;او د سرو زرو هغه دوه زنځيرونه په هغه کړو پورې وتړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2246, 'Exodus 28:25', 'Exodus', 28, 25, '&nbsp;د زنځيرونو دوه سرونه په هغه دوه څيزونو پورې وتړه چې په هغې کښې کاڼى ګېر کړے شوى دى او دا د پېش بند د اوږې په پټو باندې مخکښې طرف ته ونښلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2247, 'Exodus 28:26', 'Exodus', 28, 26, '&nbsp;بيا دوه د سرو زرو کَړۍ جوړې کړه او دا د سينې د جېب لاندې ګوټونو دننه غاړې ته د پېش بند څنګ پورې ونښلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2248, 'Exodus 28:27', 'Exodus', 28, 27, '&nbsp;دوه د سرو زرو نورې کَړۍ هم جوړې کړه او دا په لاندينۍ حِصه پورې د پېش بند د ولى دوه پټو په مخکښې ونښلوه چې ګنډ ته نزدې وى او په ګُلکارۍ ښائسته کړے شوى کمربند دپاسه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2249, 'Exodus 28:28', 'Exodus', 28, 28, '&nbsp;د سينې د جېب کَړۍ د پېش بند کړو پورې د آسمانى رنګ مزى سره وتړه، نو چې د سينې جېب په کمربند باندې پروت وى او ترې نه لرې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2250, 'Exodus 28:29', 'Exodus', 28, 29, '&nbsp;نو چې کله هارون مقدس ځائ ته ورننوځى، هغه به د سينې جېب د ځان سره وړى چې په کوم باندې د بنى اِسرائيلو د دولسو قبيلو نومونه ليکلے شوى دى، نو زۀ مالِک خُدائ به خپل خلق همېشه دپاره ياد ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2251, 'Exodus 28:30', 'Exodus', 28, 30, '&nbsp;د اُوريم او تميم کاڼى د سينې په جېب کښې کېږده، چې کله هارون زما پاک حضور ته راځى نو هغه به د ځان سره دا راوړى. په داسې وختونو کښې به هغه خامخا د سينې جېب اغوندى، چې د بنى اِسرائيلو دپاره د مالِک خُدائ رضا معلوموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2252, 'Exodus 28:31', 'Exodus', 28, 31, '&nbsp;چې کومه چُوغه د پېش بند لاندې اغوستلے کيږى هغه به ټوله د آسمانى رنګ د وړۍ نه جوړولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2253, 'Exodus 28:32', 'Exodus', 28, 32, '&nbsp;په هغې کښې به د سر دپاره يو سورے وى، چې غاړه يې مضبوطه ګنډلے شوى وى چې ونۀ شليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2254, 'Exodus 28:35', 'Exodus', 28, 35, '&nbsp;چې کله هارون د اِمام په توګه خِدمت کوى نو هغه به دا چُوغه اغوندى. چې کله هغه زما په حضور کښې مقدس ځائ ته ننوځى يا ترې نه وځى، نو د ټلو آواز به اورېدلے شى او هغه به نۀ مړ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2255, 'Exodus 28:36', 'Exodus', 28, 36, '&nbsp;د سوچه سرو زرو نه يوه نښه جوړه کړه او په هغې باندې وليکه، ”مالِک خُدائ ته وقف شوے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2256, 'Exodus 28:37', 'Exodus', 28, 37, '&nbsp;دا د يو آسمانى رنګ مزى سره د پټکى مخې ته وتړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2257, 'Exodus 28:38', 'Exodus', 28, 38, '&nbsp;هارون به دا په خپل تندى باندې وتړى، نو زۀ مالِک خُدائ به هغه نذرانې قبلوم چې بنى اِسرائيل يې ما ته وقف کوى، کۀ خلق د دې په پېش کولو کښې څۀ غلطى هم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2258, 'Exodus 28:39', 'Exodus', 28, 39, '&nbsp;د هارون دپاره د کتان نه يو قميص جوړ کړه او د کتان نه ورله پټکے جوړ کړه او يو کمربند هم جوړ کړه چې ګُلکارى ورباندې شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2259, 'Exodus 28:40', 'Exodus', 28, 40, '&nbsp;د هارون د زامنو دپاره قميصونه، کمربند او ټوپۍ جوړې کړه، چې هغوئ ته عزت او ښائست مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2260, 'Exodus 28:41', 'Exodus', 28, 41, '&nbsp;دا جامې خپل ورور هارون او د هغۀ زامنو ته ورواغونده. بيا هغوئ مقرر کړه او هغوئ ما ته وقف کولو دپاره د زيتُونو په تېلو غوړ کړه، نو داسې به هغوئ د اِمامانو په توګه زما خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2261, 'Exodus 28:42', 'Exodus', 28, 42, '&nbsp;هغوئ له د کتان نه جانګى جوړ کړه، چې د ملا نه د پنډو پورې رسيږى، نو چې د هغوئ د سَتر ځايونه بربنډ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2262, 'Exodus 28:43', 'Exodus', 28, 43, '&nbsp;هارون او د هغۀ زامن به خامخا همېشه دپاره دا اغوندى چې کله هغوئ زما په حضور کښې خېمې ته ننوځى يا چې په مقدس ځائ کښې د اِمامانو په توګه خِدمت کوى او قربان‌ګاه ته ورنزدې کيږى، ګنې د سَتر ځايونو بربنډولو په وجه به ګناهګار شى او وبه وژلے شى. د هارون او د هغۀ د اولاد دپاره به دا حُکم د همېشه دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2263, 'Exodus 29:1', 'Exodus', 29, 1, '&nbsp;هارون او د هغۀ زامن د اِمامانو په توګه زما په خِدمت کښې وقف کولو دپاره داسې وکړه چې يو سخے او دوه ګډان راونيسه چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2264, 'Exodus 29:2', 'Exodus', 29, 2, '&nbsp;د غنمو د ټولو نه ښۀ اوړۀ واخله، خو چې خمبيره په کښې نۀ وى او درې قِسمه روټۍ ترې نه پخې کړه چې د څۀ سره د زيتُونو تېل ګډ وى، څۀ چې سپورې وى او څۀ په تېلو غوړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2265, 'Exodus 29:3', 'Exodus', 29, 3, '&nbsp;دا په شکور کښې کېږده او چې کله هغه سخے او هغه دوه ګډان ما ته قربانى کړې نو دا هم ورسره راوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2266, 'Exodus 29:4', 'Exodus', 29, 4, '&nbsp;هارون او د هغۀ زامن زما د حضور خېمې دروازې ته راوله او هغوئ له غسل ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2267, 'Exodus 29:5', 'Exodus', 29, 5, '&nbsp;بيا هارون ته د اِمامانو دا لِباس ورواغونده، قميص او چُوغه چې کومه د پېش بند لاندې اغوستلے کيږى، پېش بند او د سينې جېب د ښۀ ګُلکارى شوى کمربند سره وتړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2268, 'Exodus 29:6', 'Exodus', 29, 6, '&nbsp;هغۀ ته پټکے ورپه سر کړه او په دې باندې د سرو زرو پټۍ وتړه چې هغه نښه ورباندې لګېدلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2269, 'Exodus 29:7', 'Exodus', 29, 7, '&nbsp;بيا د زيتُونو تېل واخله او د مقررولو د نښې په طور د هغۀ سر مسح کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2270, 'Exodus 29:8', 'Exodus', 29, 8, '&nbsp;د هغۀ زامن راوله او قميصونه ورواغونده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2271, 'Exodus 29:9', 'Exodus', 29, 9, '&nbsp;هغوئ ته دا کمربند وتړه او ټوپۍ ورپه سر کړه. نو تۀ به هارون او د هغۀ زامن مقرر کړې. هغوئ او د هغوئ اولاد به د اِمامانو په توګه همېشه دپاره زما خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2272, 'Exodus 29:10', 'Exodus', 29, 10, '&nbsp;هغه سخے زما د حضور خېمې مخې ته راوله او هارون او د هغۀ زامنو ته ووايه چې خپل لاسونه د هغې په سر کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2273, 'Exodus 29:11', 'Exodus', 29, 11, '&nbsp;سخے د خېمې په دروازه کښې زما په حضور کښې حلال کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2274, 'Exodus 29:12', 'Exodus', 29, 12, '&nbsp;د خپلې ګوتې سره د سخى څۀ وينه واخله او د قربان‌ګاه د څلورو ښکرونو په شان څيزونو پورې يې وسُولوه. بيا هغه پاتې وينه د قربان‌ګاه په بېخ کښې توئ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2275, 'Exodus 29:13', 'Exodus', 29, 13, '&nbsp;بيا، هغه ټوله وازګه واخله کومه چې په کولمو پرته وى، د اينې ښۀ حِصه او دواړه ګردې سره د هغه وازګې چې ورباندې پرته وى او د يوې نذرانې په توګه يې په قربان‌ګاه باندې ما ته وسوزوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2276, 'Exodus 29:14', 'Exodus', 29, 14, '&nbsp;خو د سخى غوښه، څرمن او د هغۀ سوټې د خېمو نه بهر وسوزوه. دا د اِمامانو د ګناه معاف کېدلو دپاره يوه نذرانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2277, 'Exodus 29:15', 'Exodus', 29, 15, '&nbsp;د هغه ګډانو نه يو ګډ راونيسه او هارون او د هغۀ زامنو ته ووايه چې خپل لاسونه د هغۀ په سر باندې کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2278, 'Exodus 29:16', 'Exodus', 29, 16, '&nbsp;هغه حلال کړه او وينه يې واخله او د قربان‌ګاه څلورو واړو طرفونو ته يې وشينده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2279, 'Exodus 29:17', 'Exodus', 29, 17, '&nbsp;ګډ ټوټې ټوټې کړه، د هغۀ کولمې او وروستو پښې ووينځه او دا د ګډ سر او د نورو ټوټو سره کېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2280, 'Exodus 29:18', 'Exodus', 29, 18, '&nbsp;ټول ګډ په قربان‌ګاه باندې وسوزوه، دا مالِک خُدائ ته په اور سوزېدونکې نذرانه ده. د دې خوشبوئى په هغۀ ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2281, 'Exodus 29:19', 'Exodus', 29, 19, '&nbsp;هغه بل ګډ هارون او د هغۀ زامنو له راوله او هغوئ دې خپل لاسونه د هغې په سر کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2282, 'Exodus 29:20', 'Exodus', 29, 20, '&nbsp;ګډ حلال کړه او څۀ وينه يې واخله او دا د هارون او د هغۀ د زامنو د ښى غوږُونو په نرمو ځايونو پورې، د هغوئ د ښى لاسونو په غټو ګوتو پورې او د هغوئ د ښۍ پښو په غټو ګوتو پورې ولګوه. بيا هغه پاتې وينه د قربان‌ګاه څلورو واړو طرفونو ته وشينده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2283, 'Exodus 29:21', 'Exodus', 29, 21, '&nbsp;څۀ وينه واخله چې کومه په قربان‌ګاه باندې پرته وى او څۀ د غوړولو تېل واخله او دا د هارون او د هغۀ په جامو او د هغۀ زامنو او د هغوئ په جامو باندې وشينده. نو هغه، د هغۀ زامن او د هغوئ جامې به ما ته وقف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2284, 'Exodus 29:22', 'Exodus', 29, 22, '&nbsp;د ګډ وازګه، لم، هغه وازګه چې په کولمو پرته وى، د اينې ښۀ حِصه، دواړه ګردې سره د هغه وازګې چې ورباندې وى او ښے پتُون دا ټول پرې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2285, 'Exodus 29:23', 'Exodus', 29, 23, '&nbsp;د روټۍ هغه شکور چې کوم ما ته پېش کړے شوے دے، د هر يو قِسمه روټۍ نه يوه يوه روټۍ راواخله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2286, 'Exodus 29:24', 'Exodus', 29, 24, '&nbsp;دا ټول د هارون او د هغۀ د زامنو په لاسونو کښې کېږده او هغوئ ته ووايه چې دا ټول د دې ښکاره کولو دپاره اوچت کړى چې دا مالِک خُدائ ته د خاص نذرانې په توګه وقف کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2287, 'Exodus 29:25', 'Exodus', 29, 25, '&nbsp;بيا دا د هغوئ د لاسونو نه واخله او دا په قربان‌ګاه باندې د سوزېدونکې نذرانې سره وسوزوه. د دې خوشبو هم په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2288, 'Exodus 29:26', 'Exodus', 29, 26, '&nbsp;تۀ به د دوېم ګډ پوښتۍ وخورې، خو تۀ به وړومبے دا اوچتې کړې چې ښکاره کړې چې دا غوښه ما ته وقف کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2289, 'Exodus 29:27', 'Exodus', 29, 27, '&nbsp;کله چې اِمامان مقررولے شى هغه د ګډ پوښتۍ او پتُون کوم چې د مقررولو دپاره استعماليږى هغه به اوچت کړے شى او د هارون او د هغۀ د زامنو دپاره به بېل کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2290, 'Exodus 29:28', 'Exodus', 29, 28, '&nbsp;دا زما نۀ بدلېدونکے قانون دے چې کله بنى اِسرائيل د سلامتۍ قربانۍ پېش کوى، د ځناور پوښتۍ او پتُون به د اِمامانو وى. دا زما د خلقو د طرف نه مالِک خُدائ ته نذرانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2291, 'Exodus 29:29', 'Exodus', 29, 29, '&nbsp;د هارون د اِمامت لِباس د هغۀ د مرګ نه پس به د هغۀ زامنو ته ملاويږى، ځکه چې کله هغوئ مقررولے شى نو هغوئ به دا اغوندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2292, 'Exodus 29:30', 'Exodus', 29, 30, '&nbsp;د هارون کوم زوئ چې د هغۀ په ځائ اِمام شى او چې هغه زما د حضور خېمې ته د خِدمت دپاره ننوځى نو هغه به دا لِباس اووۀ ورځې اغوندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2293, 'Exodus 29:31', 'Exodus', 29, 31, '&nbsp;د ګډ هغه غوښه واخله کومه چې د هارون او د هغۀ د زامنو په مقررولو کښې استعمال شوې وى او په يو پاک ځائ کښې يې اويشوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2294, 'Exodus 29:32', 'Exodus', 29, 32, '&nbsp;هارون او د هغۀ زامن به هغه غوښه زما د حضور خېمې په دروازه کښې د هغه روټۍ سره خورى کومه چې په شکور کښې پاتې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2295, 'Exodus 29:33', 'Exodus', 29, 33, '&nbsp;د مقرر کېدلو په وخت کښې چې د کفارې د رسم ادا کولو دپاره څۀ استعمال شوى وُو هغوئ به هغه خورى. صِرف اِمامان به دا خوراک خورى ځکه چې دا خوراک مقدس دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2296, 'Exodus 29:34', 'Exodus', 29, 34, '&nbsp;کۀ څۀ غوښه يا څۀ روټۍ تر سحره پورې پاتې شى، نو هغه به سوزولے شى، هغه به نۀ شى خوړلے، ځکه چې مقدسه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2297, 'Exodus 29:35', 'Exodus', 29, 35, '&nbsp;د هارون او د هغۀ د زامنو د مقرر کېدلو رسمونه دې اووۀ ورځې کولے شى هم هغه شان چې څنګه ما حُکم درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2298, 'Exodus 29:36', 'Exodus', 29, 36, '&nbsp;هره ورځ خامخا يو سخے د نذرانې په توګه قربانى کوئ، نو چې د ګناه کفاره ادا کيږى. دا به قربان‌ګاه پاکه کړى. د مقدس کولو دپاره يې د زيتُونو په تېلو غوړه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2299, 'Exodus 29:37', 'Exodus', 29, 37, '&nbsp;هره ورځ تر اووۀ ورځو پورې تۀ کفاره ادا کوه. نو قربان‌ګاه به بېخى مقدسه شى او هر څوک يا هر څيز چې د هغې سره ولګى نو هغه به هم مقدس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2300, 'Exodus 29:38', 'Exodus', 29, 38, '&nbsp;تۀ همېشه دپاره هره ورځ ما ته دوه ګډورى په قربان‌ګاه پېش کوه چې د يو کال وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');